import{_ as a,o as r,c as d,a2 as i}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"सहजीवी सभ्यता अधिकार-पत्र","description":"","frontmatter":{},"headers":[],"relativePath":"hi/03-共生文明宪章.md","filePath":"hi/03-共生文明宪章.md"}'),e={name:"hi/03-共生文明宪章.md"};function o(l,t,n,h,s,c){return r(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="सहजीवी-सभ्यता-अधिकार-पत्र" tabindex="-1">सहजीवी सभ्यता अधिकार-पत्र <a class="header-anchor" href="#सहजीवी-सभ्यता-अधिकार-पत्र" aria-label="Permalink to &quot;सहजीवी सभ्यता अधिकार-पत्र&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>03</td></tr><tr><td>मॉड्यूल</td><td>सामान्य सिद्धांत और मूल सेटिंग्स</td></tr><tr><td>कीवर्ड</td><td>अधिकार-पत्र, मौलिक कानून, सहजीवी संस्थाएँ, दस हजार जातियों का गणराज्य, अधिकार और कर्तव्य</td></tr></tbody></table><h2 id="i-अधिकार-पत्र-की-स्थिति-और-प्रकृति" tabindex="-1">I. अधिकार-पत्र की स्थिति और प्रकृति <a class="header-anchor" href="#i-अधिकार-पत्र-की-स्थिति-और-प्रकृति" aria-label="Permalink to &quot;I. अधिकार-पत्र की स्थिति और प्रकृति&quot;">​</a></h2><p>सहजीवी सभ्यता अधिकार-पत्र, दस हजार आत्माओं और संतुलित लंगर के मूल ब्रह्मांड में लंगर सहजीवी सभ्यता का मौलिक कानून है, और सभी कानूनों, संस्थाओं और नीतियों का सर्वोच्च आधार है। लंगर सहजीवी सभ्यता घोषणा को अपना आध्यात्मिक अग्रदूत मानते हुए, अधिकार-पत्र घोषणा के मूल प्रस्तावों को प्रवर्तनीय विधिक मानदंडों में बदल देता है। अधिकार-पत्र की वैधता हेंग युआनझोउ में सहजीवी सभ्यता से जुड़ी सभी जातियों, विमानों और व्यक्तियों को कवर करती है; अधिकार-पत्र से टकराने वाले किसी भी स्थानीय विनियमन, संप्रदाय नियम या जातीय रीति को अमान्य माना जाता है।</p><p>अधिकार-पत्र की प्रकृति को तीन बिंदुओं में संक्षेपित किया जा सकता है: पहला, यह एक सभ्यतागत अनुबंध है — सहजीवी विकास पर दस हजार जातियों के बीच हुआ मौलिक सहमति; दूसरा, यह एक अधिकार-पत्रिका है — सहजीवी सभ्यता में प्रत्येक जीवन के मौलिक अधिकारों और स्वतंत्रताओं को स्पष्ट रूप से निर्धारित करता है; तीसरा, यह शक्ति-सीमित करने वाला कानून है — सभ्यतागत शासन संस्थाओं की शक्ति के लिए अलंघनीय सीमाएँ खींचता है।</p><h2 id="ii-अधिकार-पत्र-के-मूल-सिद्धांत" tabindex="-1">II. अधिकार-पत्र के मूल सिद्धांत <a class="header-anchor" href="#ii-अधिकार-पत्र-के-मूल-सिद्धांत" aria-label="Permalink to &quot;II. अधिकार-पत्र के मूल सिद्धांत&quot;">​</a></h2><p>अधिकार-पत्र निम्नलिखित छह मूल सिद्धांत स्थापित करता है, जो उसके सभी प्रावधानों में व्याप्त हैं:</p><ol><li><strong>सहजीवन-सर्वोच्चता सिद्धांत</strong>: कोई भी संस्थागत डिज़ाइन और शक्ति-प्रयोग, दस हजार जातियों के सहजीवी विकास को बढ़ावा देना सर्वोच्च लक्ष्य मानता है। जब व्यक्तिगत हित सामूहिक सहजीवी हितों से टकराते हैं, सहजीवी हितों को प्राथमिकता दी जाती है, पर व्यक्तियों को उचित क्षतिपूर्ति और वैकल्पिक मार्ग दिए जाने चाहिए।</li><li><strong>शिकार-विरोध सिद्धांत</strong>: अधिकार-पत्र सभी प्रकार के शिकारी व्यवहार को प्रतिबंधित करता है, जिसमें ऊर्जा-शिकार, मूल-निगलन, आत्मिक दासता और संसाधन-एकाधिकार शामिल हैं पर इन्हीं तक सीमित नहीं। शिकार को केंद्र बनाने वाली कोई भी साधना प्रणाली अवैध घोषित की जाती है।</li><li><strong>विकास-अधिकार समानता सिद्धांत</strong>: विकास के अधिकार के समक्ष सभी जीवन समान हैं, बिना जाति, रूप, उत्पत्ति या प्रारंभिक स्तर के आधार पर भेदभाव के। राज्यों और सभ्यताओं का कर्तव्य है कि वे वंचित समूहों को अतिरिक्त विकास समर्थन प्रदान करें।</li><li><strong>अधिक परिश्रम, अधिक प्रतिफल सिद्धांत</strong>: विकास संसाधनों का वितरण मुख्य रूप से सहजीवी जाल में व्यक्ति के योगदान पर आधारित है; योगदान जितना अधिक, संसाधन और समर्थन उतना अधिक। साथ ही एक मूल सुरक्षा-रेखा स्थापित की जाती है, यह सुनिश्चित करने के लिए कि कम योगदान वाले व्यक्तियों को भी मूल विकास स्थितियाँ मिलें।</li><li><strong>स्वायत्तता और सह-शासन का संयोजन सिद्धांत</strong>: प्रत्येक जाति को अधिकार-पत्र का उल्लंघन न करने की शर्त पर आंतरिक मामलों में स्वायत्तता प्राप्त है; अंतर-जातीय और अंतर-विमान सार्वजनिक मामले दस हजार जातियों के गणराज्य की संस्थाओं द्वारा सह-शासित होते हैं।</li><li><strong>यथार्थ-आधार सिद्धांत</strong>: अधिकार-पत्र का सारा संस्थागत डिज़ाइन वास्तविक दुनिया को एकमात्र सत्य आधार मानता है; किसी भी काल्पनिक दुनिया के अधिकार-कर्तव्यों को यथार्थ पर हावी होने की मान्यता नहीं दी जाती।</li></ol><h2 id="iii-अधिकार-पत्र-की-मूल-संरचना" tabindex="-1">III. अधिकार-पत्र की मूल संरचना <a class="header-anchor" href="#iii-अधिकार-पत्र-की-मूल-संरचना" aria-label="Permalink to &quot;III. अधिकार-पत्र की मूल संरचना&quot;">​</a></h2><p>अधिकार-पत्र छह प्रमुख भागों से बना है: प्रस्तावना, सामान्य प्रावधान, मौलिक अधिकार और कर्तव्य, सभ्यतागत संस्थाएँ, विधिक प्रणाली और संशोधन प्रक्रियाएँ:</p><table tabindex="0"><thead><tr><th>भाग</th><th>मूल सामग्री</th><th>अनुच्छेद संख्या</th></tr></thead><tbody><tr><td>प्रस्तावना</td><td>अधिकार-पत्र की ऐतिहासिक पृष्ठभूमि, आध्यात्मिक स्रोत और अंतिम लक्ष्य स्पष्ट करता है</td><td>बिना संख्या</td></tr><tr><td>सामान्य प्रावधान</td><td>सभ्यता की प्रकृति, ब्रह्मांड-दृष्टि, मूल संस्थाएँ और मूल राज्य-नीतियाँ निर्धारित करता है</td><td>30 अनुच्छेद</td></tr><tr><td>मौलिक अधिकार और कर्तव्य</td><td>विकास का अधिकार, सूचना का अधिकार, भागीदारी का अधिकार जैसे मौलिक अधिकार और संगत कर्तव्य निर्धारित करता है</td><td>50 अनुच्छेद</td></tr><tr><td>सभ्यतागत संस्थाएँ</td><td>दस हजार जातियों के गणराज्य सभा, सहजीवी कार्यकारी समिति, लंगर न्यायालय आदि संस्थाओं के संगठन और अधिकार निर्धारित करता है</td><td>40 अनुच्छेद</td></tr><tr><td>विधिक प्रणाली</td><td>संविधान के नीचे श्रम कानून, उपभोक्ता संरक्षण कानून और पाँच सहायक कानूनों की विधायी शक्तियाँ और प्रयोग नियम निर्धारित करता है</td><td>20 अनुच्छेद</td></tr><tr><td>संशोधन प्रक्रियाएँ</td><td>अधिकार-पत्र संशोधन के प्रस्ताव, विचार-विमर्श, मतदान और प्रभावी होने की प्रक्रियाएँ निर्धारित करता है</td><td>10 अनुच्छेद</td></tr></tbody></table><h2 id="iv-मौलिक-अधिकार-और-कर्तव्य" tabindex="-1">IV. मौलिक अधिकार और कर्तव्य <a class="header-anchor" href="#iv-मौलिक-अधिकार-और-कर्तव्य" aria-label="Permalink to &quot;IV. मौलिक अधिकार और कर्तव्य&quot;">​</a></h2><p>अधिकार-पत्र द्वारा निर्धारित मूल मौलिक अधिकारों में शामिल हैं:</p><ul><li><strong>विकास चयन का अधिकार</strong>: प्रत्येक जीवन को साधना प्रणाली और विकास पथ स्वतंत्र रूप से चुनने का अधिकार है; कोई भी बाध्य नहीं कर सकता</li><li><strong>प्रणाली प्राप्ति का अधिकार</strong>: प्रत्येक जीवन को तीन सौ मूल साधना प्रणालियों के मूल विधि-मंत्र निःशुल्क प्राप्त करने का अधिकार है</li><li><strong>संसाधन आवंटन का अधिकार</strong>: प्रत्येक जीवन को उत्पादन-आधारित अनुबंध प्रणाली के माध्यम से मूल साधना संसाधन प्राप्त करने का अधिकार है</li><li><strong>लंगर-प्रवेश का अधिकार</strong>: एक निश्चित स्तर तक पहुँचने वाले प्रत्येक जीवन को संगत स्तर के लंगर जाल से जुड़ने का अधिकार है</li><li><strong>सूचना और भागीदारी का अधिकार</strong>: प्रत्येक जीवन को सभ्यता के सार्वजनिक मामलों को जानने और निर्णयों में भाग लेने का अधिकार है</li><li><strong>उपचार और अपील का अधिकार</strong>: जिस जीवन के अधिकारों का उल्लंघन हुआ है, उसे लंगर न्यायालय में अपील करने का अधिकार है</li></ul><p>संगत मूल कर्तव्यों में शामिल हैं: शिकार-विरोध सिद्धांत का पालन, लंगर जाल की स्थिरता बनाए रखना, सहजीवी प्रतिक्रिया चक्रों में भाग लेना, साधना ज्ञान का संचरण और ब्रह्मांडीय पारिस्थितिक पर्यावरण की रक्षा।</p><h2 id="v-अधिकार-पत्र-का-संशोधन-और-गारंटी" tabindex="-1">V. अधिकार-पत्र का संशोधन और गारंटी <a class="header-anchor" href="#v-अधिकार-पत्र-का-संशोधन-और-गारंटी" aria-label="Permalink to &quot;V. अधिकार-पत्र का संशोधन और गारंटी&quot;">​</a></h2><p>अधिकार-पत्र के संशोधन के लिए दस हजार जातियों के गणराज्य सभा के पाँचवें से अधिक सदस्यों का संयुक्त प्रस्ताव, सभा के दो-तिहाई से अधिक बहुमत की स्वीकृति, और ब्रह्मांडीय मूल लंगर द्वारा सहजीवी नियमों के अनुरूप सत्यापन आवश्यक है, तभी वह प्रभावी हो सकता है। अधिकार-पत्र की व्याख्या का अधिकार लंगर न्यायालय के पास है।</p><p>अधिकार-पत्र के कार्यान्वयन की गारंटी के लिए, सहजीवी सभ्यता ने संवैधानिक समीक्षा प्रणाली स्थापित की है: कोई भी कानून, विनियमन या नीति प्रभावी होने से पहले लंगर न्यायालय की संवैधानिकता समीक्षा से गुजरना चाहिए; कोई भी जीवन जो मानता है कि कोई सार्वजनिक शक्ति कार्य असंवैधानिक है, संवैधानिक मुकदमा दायर कर सकता है।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>सहजीवी सभ्यता अधिकार-पत्र लंगर सहजीवी सभ्यता की संस्थागत आधारशिला है। यह &quot;शिकार-विरोध, सहजीवन-समर्थन&quot; के आदर्श को प्रवर्तनीय, उपचार-योग्य और निगरानी-योग्य विधिक मानदंडों में बदल देता है, दस हजार जातियों की प्रगति के लिए ठोस संस्थागत गारंटी प्रदान करता है। अधिकार-पत्र कोई अपरिवर्तनीय हठधर्मिता नहीं, बल्कि एक जीवित मौलिक कानून है जो सभ्यता के विकास के साथ निरंतर परिष्कृत होता है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (लंगर सहजीवी सभ्यता घोषणा)</li><li>40-共生宪法总纲 (सहजीवी संविधान के सामान्य सिद्धांत)</li><li>49-治理框架与权力制衡 (शासन ढाँचा और शक्ति-संतुलन)</li></ul>',22)])])}const u=a(e,[["render",o]]);export{_ as __pageData,u as default};
